insert into public.lessons (level_id, slug, title, description, category, duration_minutes, sort_order, is_published)
select levels.id, lesson.slug, lesson.title, lesson.description, 'Compreensão oral', 20,
  coalesce((select max(existing.sort_order) from public.lessons as existing where existing.level_id = levels.id), 0) + lesson.level_order,
  false
from (values
    ('listening-a1-practice', 'A1', 'Inglês A1: compreensão oral', 'Diálogos e frases curtas sobre apresentações, rotina, família e objetos do dia a dia. Vinte áudios originais gerados para prática de transcrição. Todas as questões começam como rascunho para revisão.', 1),
    ('listening-a2-practice', 'A2', 'Inglês A2: compreensão oral', 'Mensagens e situações cotidianas com descrições e planos simples. Vinte áudios originais gerados para prática de transcrição. Todas as questões começam como rascunho para revisão.', 2),
    ('listening-b1-practice', 'B1', 'Inglês B1: compreensão oral', 'Narrativas curtas, experiências e situações práticas com mais detalhes. Vinte áudios originais gerados para prática de transcrição. Todas as questões começam como rascunho para revisão.', 3),
    ('listening-b2-practice', 'B2', 'Inglês B2: compreensão oral', 'Conversas e informações mais longas com condicionais, opiniões e explicações. Vinte áudios originais gerados para prática de transcrição. Todas as questões começam como rascunho para revisão.', 4),
    ('listening-c1-practice', 'C1', 'Inglês C1: compreensão oral', 'Discursos articulados com linguagem formal, inferências e estruturas avançadas. Vinte áudios originais gerados para prática de transcrição. Todas as questões começam como rascunho para revisão.', 5),
    ('listening-c2-practice', 'C2', 'Inglês C2: compreensão oral', 'Trechos densos e sutis que exigem compreensão de argumentos, nuance e precisão. Vinte áudios originais gerados para prática de transcrição. Todas as questões começam como rascunho para revisão.', 6)
) as lesson(slug, level_code, title, description, level_order)
join public.languages on languages.code = 'en'
join public.language_levels as levels on levels.language_id = languages.id and levels.code = lesson.level_code
on conflict (slug) do nothing;

