    (20, 'listening-c2-practice', 'hard', 'Ouça o áudio e transcreva o que foi dito.', 'Far from being a semantic quibble, the distinction determines whether liability attaches to the institution or its agents.', 'public/audio/listening/c2-20.wav', 'Questão de compreensão oral C2, item 20. Transcrição usada para conferência; revisar antes de publicar.')
), prepared_questions as (
  select question_data.*, source_number::smallint as question_order
  from question_data
), inserted_questions as (
  insert into public.questions (lesson_id, question_type, prompt, choices, audio_path, sort_order, is_published, difficulty)
  select lessons.id, 'listening', prepared.prompt, '[]'::jsonb, prepared.audio_path, prepared.question_order, false, prepared.difficulty
  from prepared_questions as prepared
  join public.lessons on lessons.slug = prepared.lesson_slug
  on conflict (lesson_id, sort_order) do nothing
  returning id, lesson_id, sort_order
)
insert into public.question_answers (question_id, accepted_answers, explanation)
select inserted.id, array[prepared.accepted_answer], prepared.explanation
from inserted_questions as inserted
join public.lessons on lessons.id = inserted.lesson_id
join prepared_questions as prepared
  on prepared.lesson_slug = lessons.slug
  and prepared.question_order = inserted.sort_order;
